package com.trustserve;
import org.springframework.stereotype.Component;import org.springframework.boot.CommandLineRunner;import org.springframework.beans.factory.annotation.Value;import org.springframework.security.crypto.bcrypt.BCryptPasswordEncoder;
@Component public class Seed implements CommandLineRunner {
final AccountRepository users;final ProfessionalProfileRepository pros;final HomeServiceRepository services;final ServiceCategoryRepository cats;final BCryptPasswordEncoder encoder;
@Value("${trustserve.seed}")boolean enabled;@Value("${trustserve.demo-password}")String password;
public Seed(AccountRepository u,ProfessionalProfileRepository p,HomeServiceRepository s,ServiceCategoryRepository c,BCryptPasswordEncoder e){users=u;pros=p;services=s;cats=c;encoder=e;}
Account account(String email,String name,String role){Account a=new Account();a.email=email;a.name=name;a.role=role;a.password=encoder.encode(password);return users.save(a);}
public void run(String...args){if(!enabled||users.count()>0)return;if(password.isBlank())throw new IllegalStateException("Set DEMO_PASSWORD (10+ chars including a digit) or SEED_DEMO=false");Rules.password(password);account("admin@trustserve.demo","Demo Administrator","ADMIN");account("customer@trustserve.demo","Aarav Shah (demo)","CUSTOMER");String[] categories={"Cleaning","Plumbing","Electrical","AC care","Appliances","Carpentry","Painting","Pest control","Maintenance","Computers"};String[] names={"Neel Patel","Arjun Mehta","Rohan Shah","Dev Joshi","Kabir Desai","Jay Parmar","Manav Trivedi","Yash Soni","Dhruv Vyas","Vivek Rao"};for(int i=0;i<categories.length;i++){ServiceCategory c=new ServiceCategory();c.name=categories[i];cats.save(c);Account a=account(i==0?"professional@trustserve.demo":"pro"+(i+1)+"@trustserve.demo",names[i]+" (demo)","PROFESSIONAL");ProfessionalProfile p=new ProfessionalProfile();p.account=a;p.skills=categories[i]+",Cleaning";p.experience=(3+i)+" years";p.verification=i<8?"Verified":i==8?"Under Review":"Rejected";p.bio="Careful work, clear communication and a tidy finish. Sample professional profile for classroom demonstrations.";pros.save(p);}
String[][] data={{"Basic home cleaning","Cleaning","799","90"},{"Deep home cleaning","Cleaning","1499","180"},{"Full home cleaning","Cleaning","2499","300"},{"Tap & leakage repair","Plumbing","299","60"},{"Bathroom plumbing check","Plumbing","499","90"},{"Electrical safety visit","Electrical","349","60"},{"Fan installation","Electrical","449","60"},{"AC servicing","AC care","699","90"},{"AC installation","AC care","1499","120"},{"Washing machine repair","Appliances","399","60"},{"Furniture repair","Carpentry","499","90"},{"Room painting visit","Painting","599","60"},{"General pest treatment","Pest control","999","120"},{"Home maintenance visit","Maintenance","599","90"},{"Computer diagnosis","Computers","399","60"}};
for(String[] d:data){HomeService s=new HomeService();s.name=d[0];s.category=cats.findAll().stream().filter(c->c.name.equals(d[1])).findFirst().orElseThrow();s.description=switch(d[1]){case "Cleaning"->"A fresh start for your space. Everyday surfaces, floors and the corners that need a little attention.";case "Plumbing"->"From dripping taps to stubborn leaks, get the little things working properly again.";default->"Thoughtful help from a local professional. Clear scope, upfront visit pricing and no surprises.";};s.price=Integer.parseInt(d[2]);s.duration=Integer.parseInt(d[3]);s.image="/images/"+(d[1].equals("Cleaning")?"cleaning":d[1].equals("Plumbing")?"plumbing":"home")+".jpg";services.save(s);}}
}